set-variable.value:
@{
            var auth = context.Request.Headers.GetValueOrDefault("Authorization","");
            if (string.IsNullOrEmpty(auth)) return "unknown";
            var token = auth.Replace("Bearer ", "");
            var parts = token.Split('.');
            if (parts.Length != 3) return "unknown";
            var payload = parts[1];
            payload = payload.Replace('-', '+').Replace('_', '/');
            switch (payload.Length % 4) {
                case 2: payload += "=="; break;
                case 3: payload += "="; break;
            }
            var json = System.Text.Encoding.UTF8.GetString(Convert.FromBase64String(payload));
            var obj = Newtonsoft.Json.Linq.JObject.Parse(json);
            return (string)obj["tid"] ?? "unknown";
        }

return-response.set-body:
@{
                        return "{\"error\": \"Monthly AI credit quota exceeded for tenant " + (string)context.Variables["tenantId"] + "\"}";
                    }

set-header.value:
@{
                try {
                    var resp = ((IResponse)context.Variables["creditResponse"]);
                    if (resp.StatusCode == 200) {
                        var body = resp.Body.As();
                        var obj = Newtonsoft.Json.Linq.JObject.Parse(body);
                        return (string)obj["remaining"] ?? "unknown";
                    }
                } catch {}
                return "unknown";
            }
